/* Mathematik – Anwendungen im Beruf – version allemande, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"Mod. 4","t":"Proportionalität und Dreisatz","g":"Eine Menge, eine Zeit oder Kosten aus einer bekannten Situation vorausberechnen","col":"teal","ic":"ratio","ch":[{"k":"qcm","q":"Wann sind zwei Grössen direkt proportional?","a":["Verdoppelt sich die eine, verdoppelt sich auch die andere","Verdoppelt sich die eine, halbiert sich die andere","Ihre Summe bleibt immer gleich","Ihre Differenz bleibt immer gleich"],"ex":"Gleiche Richtung, gleiches Verhältnis: Wird die eine mit einer Zahl multipliziert, wird die andere mit derselben Zahl multipliziert.","ref":"Lektion 4.1"},{"k":"tf","q":"Ein Transport mit fester Pauschale plus Kilometerpreis ist direkt proportional zur Distanz.","v":false,"ex":"Nein: Die Pauschale wird nur einmal bezahlt, 200 km kosten also nicht doppelt so viel wie 100 km.","ref":"Lektion 4.1"},{"k":"num","q":"5 gleiche Kartons wiegen 40 kg. Wie viel wiegen 8 Kartons?","n":64,"tol":0,"u":"kg","ex":"1 Karton: 40 ÷ 5 = 8 kg. 8 Kartons: 8 × 8 = 64 kg.","ref":"Lektion 4.1"},{"k":"num","q":"15 gleiche Kartons wiegen zusammen 180 kg. Wie schwer sind 22 Kartons?","n":264,"tol":0,"u":"kg","ex":"1 Karton: 180 ÷ 15 = 12 kg. 22 Kartons: 22 × 12 = 264 kg.","ref":"Lektion 4.1"},{"k":"num","q":"9 Paletten enthalten zusammen 432 Kartons. Wie viele Kartons enthalten 15 gleiche Paletten?","n":720,"tol":0,"u":"Kartons","ex":"1 Palette: 432 ÷ 9 = 48 Kartons. 15 Paletten: 15 × 48 = 720 Kartons.","ref":"Lektion 4.1"},{"k":"case","s":"Der Teamleiter der Plattform Logimax plant den morgigen Tag. Heute haben 6 Kommissionierende 420 Aufträge bearbeitet. Morgen arbeiten 8 Kommissionierende im gleichen Tempo.","q":"Wie viele Aufträge kann das Team morgen bearbeiten?","a":["560 Aufträge","490 Aufträge","600 Aufträge","630 Aufträge"],"ex":"1 Person: 420 ÷ 6 = 70 Aufträge. 8 Personen: 8 × 70 = 560 Aufträge.","ref":"Lektion 4.1"},{"k":"num","q":"2 Lagermitarbeitende räumen eine Lieferung in 6 Stunden ein. Wie viele Stunden brauchen 3 Lagermitarbeitende im gleichen Tempo?","n":4,"tol":0,"u":"Stunden","ex":"Gesamtarbeit: 2 × 6 = 12 Arbeitsstunden. Mit 3 Personen: 12 ÷ 3 = 4 Stunden.","ref":"Lektion 4.2"},{"k":"num","q":"6 Mitarbeitende beenden eine Inventur in 8 Stunden. Wie viele Stunden brauchen 12 Mitarbeitende im gleichen Tempo?","n":4,"tol":0,"u":"Stunden","ex":"Gesamtarbeit: 6 × 8 = 48 Arbeitsstunden. 48 ÷ 12 = 4 Stunden.","ref":"Lektion 4.2"},{"k":"case","s":"An der Rampe der Transvalor AG entladen 4 Gabelstapler eine grosse Lieferung in 6 Stunden. Um die Rampe schneller freizugeben, setzt der Verantwortliche 8 gleiche Stapler ein.","q":"Wie lange dauert das Entladen mit 8 Staplern?","a":["3 Stunden","12 Stunden","4 Stunden","2 Stunden"],"ex":"Umgekehrte Proportionalität: 4 × 6 = 24 Staplerstunden. 24 ÷ 8 = 3 Stunden. Mehr Stapler, also weniger Zeit.","ref":"Lektion 4.2"},{"k":"num","q":"5 Stapler entladen einen Lastwagen in 50 Minuten. Wie viele Minuten braucht es mit 10 gleichen Staplern?","n":25,"tol":0,"u":"Minuten","ex":"5 × 50 = 250 Staplerminuten. 250 ÷ 10 = 25 Minuten.","ref":"Lektion 4.2"},{"k":"sort","q":"Ordnen Sie jede Situation zu: direkt oder umgekehrt proportional?","c":["Direkt","Umgekehrt"],"it":[["Anzahl gleicher Kartons und Gesamtgewicht",0],["Anzahl Personen und Dauer einer Inventur",1],["Geschwindigkeit und Fahrzeit auf einer festen Strecke",1],["Anzahl Etiketten und Gesamtpreis",0],["Anzahl Paletten und Bodenfläche",0],["Anzahl Stapler und Entladezeit",1]],"ex":"Direkt: gleiche Richtung. Umgekehrt: Gegenrichtung (mehr Personen oder mehr Tempo, weniger Zeit).","ref":"Lektion 4.2"},{"k":"tf","q":"Bei umgekehrter Proportionalität bleibt das Produkt der beiden Grössen gleich.","v":true,"ex":"Ja: 2 Personen × 6 h = 3 Personen × 4 h = 12 Arbeitsstunden.","ref":"Lektion 4.2"},{"k":"fill","q":"Bei direkter Proportionalität bleibt das ___ der beiden Grössen gleich.","a":["Verhältnis","Produkt","Total","Differenz"],"ex":"Direkt: Das Verhältnis ist konstant (Gewicht eines Kartons, Preis eines Artikels). Umgekehrt: Das Produkt ist konstant.","ref":"Lektion 4.2"},{"k":"num","q":"Ein Lastwagen verbraucht 30 L auf 100 km. Wie viele Liter verbraucht er für 250 km?","n":75,"tol":0,"u":"L","ex":"1 km: 30 ÷ 100 = 0.3 L. 250 km: 0.3 × 250 = 75 L.","ref":"Lektion 4.3"},{"k":"case","s":"Ein Chauffeur von TransLéman muss 365 km vom Depot entfernt liefern. Sein Lastwagen verbraucht 28 L Diesel auf 100 km. Er will wissen, wie viel Treibstoff er für die Hinfahrt braucht.","q":"Wie viel Treibstoff muss eingeplant werden?","a":["102.2 L","93.8 L","112.0 L","130.4 L"],"ex":"1 km: 28 ÷ 100 = 0.28 L. 365 km: 0.28 × 365 = 102.2 L.","ref":"Lektion 4.3"},{"k":"num","q":"Ein Fahrzeug fährt mit 60 km/h. Wie viele Minuten braucht es für 150 km?","n":150,"tol":0,"u":"Minuten","ex":"60 km in 60 Min., also 1 km pro Minute. 150 km: 150 Min., also 2 h 30 Min.","ref":"Lektion 4.3"},{"k":"qcm","q":"Eine Dauer von 5.5 h entspricht…","a":["5 h 30 Min.","5 h 50 Min.","5 h 05 Min.","5 h 55 Min."],"ex":"1 Stunde = 60 Minuten, nicht 100: 0.5 h = 30 Min. 5.5 h = 5 h 30 Min.","ref":"Lektion 4.3"},{"k":"case","s":"Ein Lieferwagen hat 240 km in 4 Stunden mit konstanter Geschwindigkeit zurückgelegt. Es bleibt eine Tour von 330 km im gleichen Tempo, und der Disponent will die Ankunftszeit wissen.","q":"Wie lange dauert es für 330 km?","a":["5 h 30 Min.","4 h 50 Min.","5 h 15 Min.","6 h 00 Min."],"ex":"240 km in 240 Min., also 1 km pro Minute. 330 km: 330 Min. = 5 h 30 Min.","ref":"Lektion 4.3"},{"k":"num","q":"750 Etiketten kosten CHF 45.00. Wie viele Franken kosten 1’200 Etiketten zum gleichen Stückpreis?","n":72,"tol":0,"u":"CHF","ex":"1 Etikette: 45 ÷ 750 = CHF 0.06. 1’200 Etiketten: 1’200 × 0.06 = CHF 72.00.","ref":"Lektion 4.3"},{"k":"case","s":"Der Lagermitarbeiter von Logipack bestellt Verpackungsfolien. Die letzte Lieferung von 400 Folien kostete CHF 68.00. Diesmal braucht es 650 Stück zum gleichen Stückpreis.","q":"Wie hoch wird der Bestellbetrag?","a":["CHF 110.50","CHF 102.00","CHF 115.60","CHF 119.00"],"ex":"1 Folie: 68 ÷ 400 = CHF 0.17. 650 Folien: 650 × 0.17 = CHF 110.50. Man rechnet mit dem genauen Stückpreis und rundet erst am Schluss.","ref":"Lektion 4.3"},{"k":"order","q":"Bringen Sie die Methode «zurück zur Einheit» in die richtige Reihenfolge.","a":["Bekannte und gesuchte Grösse bestimmen","Dividieren, um den Wert für 1 Einheit zu finden","Mit der verlangten Anzahl Einheiten multiplizieren","Prüfen, ob das Ergebnis in die richtige Richtung geht"],"ex":"Man dividiert, um die Einheit zu finden, multipliziert, um das Ergebnis zu finden, und prüft dann die Richtung.","ref":"Lektion 4.1"},{"k":"num","q":"2 Kommissionierende bearbeiten 120 Pakete in 3 Stunden. Wie viele Pakete bearbeiten 4 Kommissionierende in 2 Stunden im gleichen Tempo?","n":160,"tol":0,"u":"Pakete","ex":"Leistung: 120 ÷ 2 ÷ 3 = 20 Pakete pro Person und Stunde. 20 × 4 × 2 = 160 Pakete.","ref":"Lektion 4.4"},{"k":"case","s":"Bei Distrivaud haben 4 Kommissionierende 560 Pakete in 7 Stunden bearbeitet. Morgen zählt das Team 6 Personen, aber nur während 5 Stunden.","q":"Wie viele Pakete kann das Team morgen bearbeiten?","a":["600 Pakete","560 Pakete","630 Pakete","720 Pakete"],"ex":"Leistung: 560 ÷ 4 ÷ 7 = 20 Pakete pro Person und Stunde. 20 × 6 × 5 = 600 Pakete.","ref":"Lektion 4.4"},{"k":"case","s":"Gestern haben 6 Mitarbeitende 900 Pakete in 5 Stunden vorbereitet. Heute müssen 1’440 Pakete raus, und bis zur Abholung durch den Transporteur bleiben nur 4 Stunden.","q":"Wie viele Mitarbeitende müssen eingesetzt werden?","a":["12 Mitarbeitende","10 Mitarbeitende","14 Mitarbeitende","16 Mitarbeitende"],"ex":"Leistung: 900 ÷ 6 ÷ 5 = 30 Pakete pro Person und Stunde. 1’440 ÷ (30 × 4) = 12 Mitarbeitende.","ref":"Lektion 4.4"},{"k":"case","s":"Eine Person kommissioniert 25 Pakete pro Stunde. Ein dringender Auftrag von 1’000 Paketen muss in 6 Stunden bereit sein. Der Teamleiter berechnet das nötige Personal.","q":"Wie viele Kommissionierende müssen eingeplant werden?","a":["7 Kommissionierende","6 Kommissionierende","8 Kommissionierende","5 Kommissionierende"],"ex":"1’000 ÷ (25 × 6) = 6.67. Man rundet auf: Man kann keinen Bruchteil einer Person einsetzen, also 7 Kommissionierende.","ref":"Lektion 4.4"},{"k":"num","q":"Ein Lastwagen verbraucht 24 L auf 100 km. Er macht 3 Fahrten zu je 175 km. Wie viele Liter verbraucht er insgesamt?","n":126,"tol":0,"u":"L","ex":"Gesamtstrecke: 3 × 175 = 525 km. 0.24 × 525 = 126 L.","ref":"Lektion 4.4"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche Situation ist NICHT direkt proportional?","a":["Anzahl Staplerfahrer und Entladedauer","Anzahl Paletten und Bodenfläche","Betriebszeit und produzierte Stücke","Anzahl Etiketten und Gesamtpreis"],"ex":"Mehr Staplerfahrer, weniger Zeit: Das ist umgekehrte Proportionalität.","ref":"Lektion 4.2"},{"k":"match","q":"Ordnen Sie jeder Angabe aus dem Beruf ihren Wert für 1 Einheit zu.","p":[["30 L/100 km","0.3 L pro km"],["60 km/h","1 km pro Minute"],["120 Pakete in 8 Min.","15 Pakete pro Minute"],["CHF 45.00 für 750 Etiketten","CHF 0.06 pro Etikette"]],"ex":"Man dividiert, um auf 1 Einheit zu kommen: 30 ÷ 100, 60 ÷ 60, 120 ÷ 8, 45 ÷ 750.","ref":"Lektion 4.3"},{"k":"multi","q":"Welche Situationen sind umgekehrt proportional?","good":["Anzahl Personen und Dauer des Einräumens","Anzahl Stapler und Entladezeit","Geschwindigkeit und Fahrzeit auf 200 km"],"bad":["Anzahl Kartons und Gesamtgewicht","Anzahl Etiketten und Gesamtpreis"],"ex":"Umgekehrt: Nimmt die eine zu, nimmt die andere ab (das Produkt bleibt gleich).","ref":"Lektion 4.2"},{"k":"case","s":"Zwei Lagermitarbeitende haben eine Lieferung in 6 Stunden eingeräumt. Für die nächste, gleiche Lieferung sind sie zu dritt. Ein Kollege sagt: «Das dauert 9 Stunden.»","q":"Was antworten Sie?","a":["Nein: 12 Arbeitsstunden ÷ 3 = 4 Stunden","Ja: 6 ÷ 2 × 3 = 9 Arbeitsstunden","Nein: 6 − 1 = 5 Stunden, eine Person mehr","Ja: Mit mehr Personen dauert die Arbeit länger"],"ex":"Klassischer Fehler: direkte Proportionalität anwenden. Mit mehr Personen kann die Arbeit nicht länger dauern. 2 × 6 = 12; 12 ÷ 3 = 4 h.","ref":"Lektion 4.2"},{"k":"case","s":"Ein Förderband im Sortierzentrum befördert 840 Pakete in 35 Minuten. Der Verantwortliche will wissen, wie viele es in 50 Minuten im gleichen Tempo sind.","q":"Wie viele Pakete laufen in 50 Minuten durch?","a":["1’200 Pakete","1’050 Pakete","1’260 Pakete","1’400 Pakete"],"ex":"1 Minute: 840 ÷ 35 = 24 Pakete. 50 Minuten: 24 × 50 = 1’200 Pakete.","ref":"Lektion 4.3"}]},{"code":"Mod. 5","t":"Prozentrechnen für Fortgeschrittene","g":"Quoten, Rabatte, Erhöhungen und Senkungen lesen und berechnen","col":"indigo","ic":"percent","ch":[{"k":"qcm","q":"Was bedeutet «Prozent»?","a":["Von 100","Mal 100","Geteilt durch 10","Von 1’000"],"ex":"Ein Prozentsatz gibt an, wie viele Teile man hätte, wenn das Total auf 100 gebracht würde.","ref":"Lektion 5.1"},{"k":"num","q":"Von 200 erhaltenen Paketen sind 6 beschädigt. Wie hoch ist die Bruchrate in %?","n":3,"tol":0,"u":"%","ex":"6 ÷ 200 = 0.03; 0.03 × 100 = 3 %.","ref":"Lektion 5.1"},{"k":"case","s":"Im Wareneingang von Logiplus hat der Kontrolleur heute Morgen 12 beschädigte Pakete von 300 erhaltenen gezählt. Die Qualitätsverantwortliche fragt nach der Bruchrate.","q":"Wie hoch ist die Bruchrate?","a":["4 %","4.2 %","12 %","0.04 %"],"ex":"Bruchrate = beschädigte Pakete ÷ erhaltene Pakete × 100 = 12 ÷ 300 × 100 = 4 %. Bezugsgrösse sind die erhaltenen Pakete, nicht die intakten.","ref":"Lektion 5.1"},{"k":"match","q":"Ordnen Sie jeder Kennzahl ihre Berechnung zu (Teil ÷ Total).","p":[["Bruchrate","Beschädigte Pakete ÷ erhaltene Pakete"],["Kommissionierfehlerquote","Aufträge mit Fehler ÷ kommissionierte Aufträge"],["Servicegrad","Sofort gelieferte Artikel ÷ bestellte Artikel"],["Retourenquote","Retournierte Pakete ÷ versandte Pakete"]],"ex":"Überall dieselbe Formel: Teil ÷ Total × 100. Nur Teil und Total ändern.","ref":"Lektion 5.1"},{"k":"match","q":"Ordnen Sie jedem Bruch seinen Prozentsatz zu.","p":[["1/2","50 %"],["1/4","25 %"],["1/10","10 %"],["1/100","1 %"]],"ex":"Bruch → Dezimalzahl (0.5; 0.25; 0.1; 0.01) → × 100.","ref":"Lektion 5.1"},{"k":"tf","q":"Das Ergebnis 0.03 entspricht 0.03 %.","v":false,"ex":"Man muss mit 100 multiplizieren: 0.03 = 3 %.","ref":"Lektion 5.1"},{"k":"case","s":"Inventur bei Stockalp: Die Software meldet 4’850 Stück eines Artikels, die physische Zählung ergibt 4’753. Der Lagerchef will die Inventurdifferenz in %.","q":"Wie hoch ist die Inventurdifferenz?","a":["2 %","2.04 %","97 %","0.2 %"],"ex":"Differenz: 4’850 − 4’753 = 97. Bezugsgrösse: der Buchbestand. 97 ÷ 4’850 × 100 = 2 %.","ref":"Lektion 5.1"},{"k":"num","q":"Wie viel sind 15 % von 400 Artikeln?","n":60,"tol":0,"u":"Artikel","ex":"10 % = 40, 5 % = 20; 15 % = 60. Oder: 400 × 0.15 = 60.","ref":"Lektion 5.2"},{"k":"num","q":"Ein Lager zählt 400 Artikel, davon 15 % der Kategorie A. Wie viele Artikel sind NICHT in Kategorie A?","n":340,"tol":0,"u":"Artikel","ex":"400 × 0.15 = 60 A-Artikel; 400 − 60 = 340. Oder direkt 400 × 0.85 = 340.","ref":"Lektion 5.2"},{"k":"case","s":"Das Regal des Depots Morges hat 250 Lagerplätze. Die Software zeigt 64 % belegt. Der Staplerfahrer will wissen, wie viele freie Plätze ihm für den Wareneingang bleiben.","q":"Wie viele Lagerplätze sind frei?","a":["90 Lagerplätze","160 Lagerplätze","64 Lagerplätze","36 Lagerplätze"],"ex":"Frei: 100 % − 64 % = 36 %. 250 × 0.36 = 90 Lagerplätze. Falle: 64 % von 250 ergibt die belegten Plätze (160).","ref":"Lektion 5.2"},{"k":"qcm","q":"Wie schreibt man 7.5 % als Dezimalzahl?","a":["0.075","0.75","7.5","0.0075"],"ex":"Man dividiert durch 100: Der Punkt verschiebt sich um zwei Stellen nach links.","ref":"Lektion 5.2"},{"k":"num","q":"Von einem Los von 1’200 Kartons müssen 2.5 % kontrolliert werden. Wie viele Kartons sind zu kontrollieren?","n":30,"tol":0,"u":"Kartons","ex":"1’200 × 0.025 = 30 Kartons.","ref":"Lektion 5.2"},{"k":"fill","q":"Bei einer Erhöhung um 8 % ist der Multiplikationsfaktor ___.","a":["1.08","1.8","0.92","0.08"],"ex":"Erhöhung um p %: × (1 + p ÷ 100) = × 1.08. Falle: 1.8 schreiben.","ref":"Lektion 5.3"},{"k":"num","q":"Eine Rolle Folie kostet CHF 20.00. Der Lieferant gewährt 5 % Rabatt. Wie hoch ist der neue Preis in CHF?","n":19,"tol":0,"u":"CHF","ex":"Faktor: 1 − 0.05 = 0.95. 20 × 0.95 = CHF 19.00.","ref":"Lektion 5.3"},{"k":"case","s":"Eine Transportleistung wird mit CHF 50.00 ohne MWST verrechnet. Die Buchhalterin von LogiSuisse muss 8.1 % MWST hinzurechnen, um den Betrag inkl. MWST zu erhalten.","q":"Wie hoch ist der Betrag inkl. MWST?","a":["CHF 54.05","CHF 50.81","CHF 58.10","CHF 45.95"],"ex":"Faktor: 1 + 0.081 = 1.081. 50 × 1.081 = CHF 54.05.","ref":"Lektion 5.3"},{"k":"num","q":"Der Preis eines Transports steigt von CHF 50.00 auf CHF 55.00. Um wie viele % ist er gestiegen?","n":10,"tol":0,"u":"%","ex":"Differenz: 55 − 50 = 5. 5 ÷ 50 × 100 = 10 %. Man vergleicht immer mit dem alten Wert.","ref":"Lektion 5.3"},{"k":"case","s":"Der Preis einer Palette Spanngurte sinkt dank eines neuen Angebots von CHF 80.00 auf CHF 68.00. Der Einkäufer will die Veränderung in % für seinen Bericht.","q":"Wie hat sich der Preis verändert?","a":["Senkung um 15 %","Senkung um 17.6 %","Senkung um 12 %","Erhöhung um 15 %"],"ex":"(68 − 80) ÷ 80 × 100 = −15 %: Senkung um 15 %. Falle: durch den neuen Wert dividieren (12 ÷ 68 = 17.6 %).","ref":"Lektion 5.3"},{"k":"qcm","q":"Um eine Veränderung in % zu berechnen, dividiert man die Differenz durch…","a":["Den alten Wert","Den neuen Wert","Die Summe beider Werte","100"],"ex":"Der Ausgangswert ist immer die Bezugsgrösse.","ref":"Lektion 5.3"},{"k":"sort","q":"Ordnen Sie jeden Multiplikationsfaktor zu: Erhöhung oder Senkung?","c":["Erhöhung","Senkung"],"it":[["× 1.081 (MWST)",0],["× 0.95",1],["× 1.10",0],["× 0.90",1],["× 0.855",1],["× 1.025",0]],"ex":"Faktor grösser als 1: Erhöhung. Kleiner als 1: Senkung.","ref":"Lektion 5.3"},{"k":"case","s":"Ein Kartonlieferant gewährt Logimax 10 % Rabatt auf ein Los zu CHF 200.00 und danach 5 % Treuerabatt auf den bereits reduzierten Preis.","q":"Wie hoch ist der Endpreis des Loses?","a":["CHF 171.00","CHF 170.00","CHF 172.50","CHF 180.00"],"ex":"200 × 0.90 × 0.95 = CHF 171.00. Rabatte werden nicht addiert: Der Gesamtrabatt beträgt 14.5 %, nicht 15 %.","ref":"Lektion 5.4"},{"k":"tf","q":"Ein Rabatt von 10 % und danach ein Rabatt von 5 % ergeben einen Gesamtrabatt von 15 %.","v":false,"ex":"Man multipliziert die Faktoren: 0.90 × 0.95 = 0.855, also ein Rabatt von 14.5 %.","ref":"Lektion 5.4"},{"k":"num","q":"Ein Bestand von 1’000 Stück steigt um 10 % und sinkt danach um 10 %. Wie viele Stück bleiben?","n":990,"tol":0,"u":"Stück","ex":"1’000 × 1.10 = 1’100; 1’100 × 0.90 = 990. Die Senkung bezieht sich auf 1’100: Man kommt nicht auf 1’000 zurück.","ref":"Lektion 5.4"},{"k":"case","s":"Dank eines neuen Scanners ist die Kommissionierfehlerquote des Lagers von 5 % auf 3.5 % gesunken. Die Geschäftsleitung fragt, um wie viel sie relativ gesunken ist.","q":"Um wie viel % ist die Fehlerquote gesunken?","a":["30 %","1.5 %","3.5 %","15 %"],"ex":"Differenz: 1.5 Prozentpunkte. Relativ: 1.5 ÷ 5 × 100 = 30 %.","ref":"Lektion 5.4"},{"k":"qcm","q":"Eine Fehlerquote sinkt von 5 % auf 3.5 %. Um wie viele Prozentpunkte ist sie gesunken?","a":["1.5 Prozentpunkte","30 Prozentpunkte","3.5 Prozentpunkte","8.5 Prozentpunkte"],"ex":"5 − 3.5 = 1.5 Prozentpunkte. Relativ ist das eine Senkung um 30 %.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Los von 2’000 Artikeln kommt in die Qualitätskontrolle. 8 % sind nicht konform. Von den konformen Artikeln gehen 20 % per Express, der Rest als Standardsendung.","q":"Wie viele Artikel gehen per Express weg?","a":["368 Artikel","400 Artikel","320 Artikel","1’472 Artikel"],"ex":"Konform: 2’000 × 0.92 = 1’840. Express: 1’840 × 0.20 = 368. Die 20 % gelten für die konformen Artikel, nicht für das Total.","ref":"Lektion 5.4"},{"k":"order","q":"Bringen Sie die Methode für mehrere aufeinanderfolgende Prozentsätze in die richtige Reihenfolge.","a":["Das Problem in Schritte zerlegen, in der Reihenfolge der Aufgabe","Fragen, auf welche Menge sich der Prozentsatz bezieht","Das Ergebnis des Schritts berechnen","Dieses Ergebnis als Basis für den nächsten Schritt nehmen"],"ex":"Jeder Prozentsatz gilt für das Ergebnis des vorherigen Schritts.","ref":"Lektion 5.4"},{"k":"odd","q":"Finden Sie den Ausreisser unter diesen Faktoren.","a":["× 1.05","× 0.90","× 0.95","× 0.75"],"ex":"× 1.05 ist eine Erhöhung um 5 %; die anderen sind Senkungen (10 %, 5 %, 25 %).","ref":"Lektion 5.3"},{"k":"multi","q":"Welche Aussagen sind richtig?","good":["Die Bruchrate wird auf die erhaltenen Pakete berechnet","Eine Veränderung wird mit dem Ausgangswert verglichen","Faktoren aufeinanderfolgender Prozentsätze werden multipliziert"],"bad":["Aufeinanderfolgende Prozentsätze werden addiert","Man dividiert die Differenz durch den neuen Wert"],"ex":"Immer fragen «von wie vielen?» und aufeinanderfolgende Prozentsätze nie addieren.","ref":"Lektion 5.4"},{"k":"case","s":"Im Oktober hat der Onlineshop von Logiplus 1’200 Pakete versandt. 36 Pakete wurden von Kunden retourniert. Der Kundendienst will die Retourenquote des Monats.","q":"Wie hoch ist die Retourenquote?","a":["3 %","3.6 %","36 %","0.3 %"],"ex":"Retournierte Pakete ÷ versandte Pakete × 100 = 36 ÷ 1’200 × 100 = 3 %.","ref":"Lektion 5.1"},{"k":"num","q":"Eine Rechnung beträgt CHF 1’000.00 ohne MWST. Wie hoch ist der Betrag inkl. 8.1 % MWST, in CHF?","n":1081,"tol":0,"u":"CHF","ex":"1’000 × 1.081 = CHF 1’081.00.","ref":"Lektion 5.3"},{"k":"case","s":"Ein Kunde hat bei Distrivaud 480 Artikel bestellt. 456 konnten sofort geliefert werden, die übrigen folgen später. Die Verantwortliche berechnet den Servicegrad.","q":"Wie hoch ist der Servicegrad?","a":["95 %","5 %","105.3 %","4.8 %"],"ex":"Sofort gelieferte Artikel ÷ bestellte Artikel × 100 = 456 ÷ 480 × 100 = 95 %.","ref":"Lektion 5.1"}]},{"code":"Mod. 6","t":"Füllgrad und Kapazität","g":"Die Belegung eines Lagers oder Fahrzeugs und den freien Platz messen","col":"violet","ic":"fill","ch":[{"k":"num","q":"Ein Regal hat 200 Lagerplätze, davon sind 150 belegt. Wie hoch ist der Belegungsgrad in %?","n":75,"tol":0,"u":"%","ex":"150 ÷ 200 × 100 = 75 %.","ref":"Lektion 6.1"},{"k":"tf","q":"Belegungsgrad und freier Anteil ergeben zusammen immer 100 %.","v":true,"ex":"Freier Anteil = 100 % − Belegungsgrad.","ref":"Lektion 6.1"},{"k":"case","s":"Das Palettenregal von Stockalp hat 320 Lagerplätze. Heute Morgen sind 248 belegt. Der Lagerchef bereitet seinen Wochenbericht vor.","q":"Wie hoch ist der Belegungsgrad?","a":["77.5 %","22.5 %","72.0 %","129.0 %"],"ex":"248 ÷ 320 × 100 = 77.5 %. Die 22.5 % entsprechen dem freien Anteil.","ref":"Lektion 6.1"},{"k":"qcm","q":"Ab welchem Belegungsgrad legen viele Unternehmen eine Warnschwelle fest?","a":["Etwa 85 bis 90 %","Etwa 50 %","Genau 100 %","Etwa 25 bis 30 %"],"ex":"Ein fast volles Lager ist unflexibel: Die Warnschwelle liegt oft bei etwa 85 bis 90 %.","ref":"Lektion 6.1"},{"k":"case","s":"Der Direktor von Logimax ist stolz: Sein Lager ist zu 98 % belegt. Trotzdem klagen die Kommissionierenden, und die Fehler nehmen seit einigen Wochen zu.","q":"Was ist das Problem bei einem so hohen Wert?","a":["Kein Platz mehr für einen unerwarteten Wareneingang","Die Miete des Lagers wird höher","Die Paletten werden schwerer zu heben","Der freie Anteil übersteigt dann 100 %"],"ex":"Ein fast volles Lager ist unflexibel: Unerwartete Wareneingänge sind schwierig, Wege und Fehler nehmen zu.","ref":"Lektion 6.1"},{"k":"tf","q":"Ein sehr tiefer Belegungsgrad zeigt bezahlte, aber ungenutzte Fläche.","v":true,"ex":"Das ist das andere Extrem: Man bezahlt Platz für nichts.","ref":"Lektion 6.1"},{"k":"num","q":"Ein Lieferwagen hat eine Nutzlast von 1’000 kg. Er transportiert 800 kg. Wie hoch ist sein Auslastungsgrad in %?","n":80,"tol":0,"u":"%","ex":"800 ÷ 1’000 × 100 = 80 %.","ref":"Lektion 6.2"},{"k":"num","q":"Ein Lastwagen hat eine Nutzlast von 15 t. Er transportiert 12 t. Wie hoch ist sein Auslastungsgrad in %?","n":80,"tol":0,"u":"%","ex":"12 ÷ 15 × 100 = 80 %. Beide Werte sind bereits in Tonnen.","ref":"Lektion 6.2"},{"k":"case","s":"Ein Lieferwagen hat eine Nutzlast von 3.5 t. Der Fahrer hat 2’800 kg Waren geladen und will seinen Auslastungsgrad kontrollieren.","q":"Wie hoch ist der Auslastungsgrad?","a":["80 %","0.8 %","125 %","8 %"],"ex":"Zuerst umrechnen: 3.5 t = 3’500 kg. 2’800 ÷ 3’500 × 100 = 80 %.","ref":"Lektion 6.2"},{"k":"sort","q":"Ordnen Sie jede Kapazität ihrer Messgrösse zu.","c":["Gewicht","Volumen","Anzahl Einheiten"],"it":[["Nutzlast eines Lastwagens",0],["Zulässige Last einer Palette",0],["Nutzvolumen eines Containers",1],["Fassungsvermögen eines Tanks",1],["Palettenplätze eines Sattelaufliegers",2],["Fächer eines automatischen Lagers",2]],"ex":"Gewicht: kg, t. Volumen: m³, L. Einheiten: Paletten, Behälter, Fächer.","ref":"Lektion 6.2"},{"k":"case","s":"Ein Lastwagen von Transvalor lädt leere Verpackungskartons, sehr voluminös, aber leicht. Der Chauffeur fragt sich, welche Grenze er zuerst erreicht.","q":"Welche Grenze wird zuerst erreicht?","a":["Das Volumen, lange vor der Nutzlast","Die Nutzlast, lange vor dem Volumen","Beide Grenzen genau gleichzeitig","Keine, der Lastwagen wird nie voll"],"ex":"Leichte und voluminöse Waren füllen den Raum lange bevor die Nutzlast erreicht ist.","ref":"Lektion 6.2"},{"k":"qcm","q":"Eine Rechnung ergibt 22 ÷ 26 × 100 = 84.615… %. Wie lautet das auf eine Dezimale gerundete Ergebnis?","a":["84.6 %","84.7 %","84.0 %","85.0 %"],"ex":"Hundertstelziffer: 1, also bleibt die Zehntelziffer: 84.6 %.","ref":"Lektion 6.2"},{"k":"num","q":"Ein Regal mit 320 Lagerplätzen hat 248 belegte. Wie viele Lagerplätze sind verfügbar?","n":72,"tol":0,"u":"Lagerplätze","ex":"320 − 248 = 72 Lagerplätze.","ref":"Lektion 6.3"},{"k":"case","s":"Das Depot von Logipack hat 400 Palettenplätze, zu 72 % belegt. Für morgen früh ist eine grosse Lieferung angekündigt.","q":"Wie viele Lagerplätze sind noch verfügbar?","a":["112 Lagerplätze","288 Lagerplätze","128 Lagerplätze","28 Lagerplätze"],"ex":"Freier Anteil: 100 % − 72 % = 28 %. 400 × 0.28 = 112 Lagerplätze. Kontrolle: 288 belegt + 112 = 400.","ref":"Lektion 6.3"},{"k":"num","q":"Ein Tank von 2’000 L ist zu 70 % gefüllt. Wie viele Liter sind noch verfügbar?","n":600,"tol":0,"u":"L","ex":"Freier Anteil: 30 %. 2’000 × 0.30 = 600 L. Kontrolle: 1’400 + 600 = 2’000 L.","ref":"Lektion 6.3"},{"k":"case","s":"Ein Container hat ein Nutzvolumen von 67.7 m³. Die bereits geladenen Waren belegen 54.16 m³. Der Spediteur will wissen, welches Volumen er noch anbieten kann.","q":"Welches Volumen bleibt verfügbar?","a":["13.54 m³","13.61 m³","12.54 m³","121.86 m³"],"ex":"67.70 − 54.16 = 13.54 m³. Bei Dezimalzahlen richtet man die Stellen nach dem Punkt aus.","ref":"Lektion 6.3"},{"k":"tf","q":"Belegte Menge + verfügbare Kapazität = Gesamtkapazität.","v":true,"ex":"Das ist die Kontrolle bei jeder Berechnung der verfügbaren Kapazität.","ref":"Lektion 6.3"},{"k":"num","q":"Ein Regal mit 100 Lagerplätzen ist zu 60 % belegt. Es werden 15 weitere Paletten eingelagert. Wie hoch ist der neue Belegungsgrad in %?","n":75,"tol":0,"u":"%","ex":"60 belegt + 15 = 75. 75 ÷ 100 × 100 = 75 %.","ref":"Lektion 6.4"},{"k":"num","q":"Ein Depot mit 100 Lagerplätzen enthält 75 Paletten. Es wird um 50 Plätze erweitert. Wie hoch ist der neue Belegungsgrad in %?","n":50,"tol":0,"u":"%","ex":"Immer noch 75 Paletten, aber 150 Lagerplätze: 75 ÷ 150 × 100 = 50 %.","ref":"Lektion 6.4"},{"k":"case","s":"Das Depot von Distrivaud hat 500 Lagerplätze, zu 80 % belegt. Am Abend gehen 160 Paletten in den Versand und geben ihre Plätze frei.","q":"Wie hoch ist der neue Belegungsgrad?","a":["48 %","64 %","32 %","52 %"],"ex":"Ausgang: 500 × 0.80 = 400. Nach dem Versand: 400 − 160 = 240. 240 ÷ 500 × 100 = 48 %.","ref":"Lektion 6.4"},{"k":"case","s":"Ein Regal mit 240 Lagerplätzen ist zu 75 % belegt. Am Vormittag werden 30 erhaltene Paletten eingelagert und 12 Paletten gehen in die Produktion.","q":"Wie hoch ist der Belegungsgrad am Mittag?","a":["82.5 %","75.0 %","93.0 %","67.5 %"],"ex":"Ausgang: 240 × 0.75 = 180. 180 + 30 − 12 = 198. 198 ÷ 240 × 100 = 82.5 %.","ref":"Lektion 6.4"},{"k":"qcm","q":"Ein Kollege schreibt «75 % + 15 Paletten = 90 %». Was ist sein Fehler?","a":["Er addiert eine Anzahl Paletten zu einem Prozentsatz","Er vergisst, das Endergebnis mit 100 zu multiplizieren","Er hätte die 15 Paletten vom Total abziehen müssen","Er hätte den Grad durch 15 Paletten teilen müssen"],"ex":"Man geht auf die tatsächlichen Mengen zurück, aktualisiert sie und berechnet den Grad neu.","ref":"Lektion 6.4"},{"k":"order","q":"Bringen Sie die Berechnung des Grades nach einer Lagerbewegung in die richtige Reihenfolge.","a":["Die belegte Menge zu Beginn bestimmen","Eingänge addieren und Ausgänge abziehen","Durch die Gesamtkapazität dividieren","Mit 100 multiplizieren"],"ex":"Auf die Mengen zurückgehen, aktualisieren, den Grad neu berechnen.","ref":"Lektion 6.4"},{"k":"match","q":"Ordnen Sie jeder Grösse ihre Berechnung zu.","p":[["Belegungsgrad","Belegt ÷ Gesamtkapazität × 100"],["Freier Anteil","100 % − Belegungsgrad"],["Verfügbare Kapazität","Gesamtkapazität − belegt"],["Auslastungsgrad","Geladene Menge ÷ maximale Kapazität × 100"]],"ex":"Grade: in %. Verfügbare Kapazität: als tatsächliche Menge (Lagerplätze, kg, m³, L).","ref":"Lektion 6.3"},{"k":"odd","q":"Finden Sie den Ausreisser: Welches Ereignis SENKT den Belegungsgrad, ohne dass eine Palette hinausgeht?","a":["Erweiterung des Depots um 50 Lagerplätze","Eingang von 20 Paletten","Kundenretoure wieder eingelagert","Einlagern einer Lieferung"],"ex":"Eine Erweiterung ändert das Total (den Nenner), nicht den Bestand. Die drei anderen erhöhen den Grad.","ref":"Lektion 6.4"},{"k":"case","s":"Ein Sattelauflieger bietet 33 Palettenplätze. Der Staplerfahrer hat 27 geladen, und der Disponent fragt nach dem Auslastungsgrad, auf eine Dezimale gerundet.","q":"Wie hoch ist der Auslastungsgrad?","a":["81.8 %","18.2 %","82.0 %","122.2 %"],"ex":"27 ÷ 33 × 100 = 81.81… → 81.8 %.","ref":"Lektion 6.2"},{"k":"multi","q":"Ein Depot wird erweitert, ohne Paletten zu verschieben. Was stimmt?","good":["Die Gesamtkapazität steigt","Die gelagerte Menge ändert sich nicht","Der Belegungsgrad sinkt"],"bad":["Paletten verlassen das Lager","Der freie Anteil sinkt"],"ex":"Eine Erweiterung ändert den Nenner, nicht den Bestand: Der Belegungsgrad sinkt und der freie Anteil steigt.","ref":"Lektion 6.4"},{"k":"fill","q":"Eine Erweiterung des Depots ändert die ___, nicht die gelagerte Menge.","a":["Gesamtzahl der Lagerplätze","Anzahl Paletten","gelagerte Gewichtsmenge","Servicegrad-Kennzahl"],"ex":"Der Nenner (Gesamtkapazität) ändert sich; der Bestand bleibt gleich.","ref":"Lektion 6.4"},{"k":"num","q":"Eine Bodenlagerfläche misst 1’200 m². 900 m² sind belegt. Wie hoch ist der Belegungsgrad in %?","n":75,"tol":0,"u":"%","ex":"900 ÷ 1’200 × 100 = 75 %.","ref":"Lektion 6.1"},{"k":"case","s":"Ein Eingang von 40 Paletten ist angekündigt. Das Regal mit 300 Lagerplätzen ist zu 90 % belegt. Der Lagermitarbeiter muss dem Transporteur sagen, ob die ganze Lieferung Platz hat.","q":"Was antwortet er?","a":["Nein: 30 Plätze frei, es fehlen 10","Ja: 30 Plätze frei, es bleiben 20","Nein: 270 Plätze frei, es fehlen 230","Ja: 40 Plätze frei, das reicht genau"],"ex":"Frei: 300 × 0.10 = 30 Lagerplätze. 40 − 30 = 10 Paletten finden keinen Platz.","ref":"Lektion 6.3"}]},{"code":"Mod. 7","t":"Palettierung und Optimierung","g":"Berechnen, wie viele Packstücke auf eine Palette passen, ohne Höhe und Gewicht zu überschreiten","col":"coral","ic":"pallet","ch":[{"k":"qcm","q":"Welche Masse hat eine EUR-Palette?","a":["1’200 × 800 mm","1’200 × 1’000 mm","1’000 × 800 mm","1’200 × 1’200 mm"],"ex":"EUR-Palette: 1’200 × 800 mm. Industriepalette: 1’200 × 1’000 mm.","ref":"Lektion 7.1"},{"k":"qcm","q":"Welche Masse hat eine Industriepalette?","a":["1’200 × 1’000 mm","1’200 × 800 mm","1’000 × 600 mm","800 × 600 mm"],"ex":"Industriepalette: 1’200 × 1’000 mm.","ref":"Lektion 7.1"},{"k":"num","q":"Wie viele Kartons von 400 × 200 mm passen pro Lage auf eine EUR-Palette?","n":12,"tol":0,"u":"Kartons","ex":"1’200 ÷ 400 = 3 und 800 ÷ 200 = 4: 3 × 4 = 12. Andere Richtung: 6 × 2 = 12. Kontrolle: 960’000 ÷ 80’000 = 12, volle Lage.","ref":"Lektion 7.1"},{"k":"case","s":"Der Kommissionierer von Logipack muss Kartons von 300 × 400 mm auf eine EUR-Palette stapeln. Er ist unsicher, in welche Richtung er die Kartons legen soll.","q":"Wie viele Kartons passen höchstens pro Lage?","a":["8 Kartons","6 Kartons","7 Kartons","10 Kartons"],"ex":"300 auf der Länge: 4 × 2 = 8. 400 auf der Länge: 3 × 2 = 6. Man nimmt die beste Ausrichtung: 8 Kartons.","ref":"Lektion 7.1"},{"k":"num","q":"Wie viele Kartons von 600 × 400 mm passen pro Lage auf eine EUR-Palette?","n":4,"tol":0,"u":"Kartons","ex":"600 auf der Länge: 2 × 2 = 4. 400 auf der Länge: 3 × 1 = 3. Maximum: 4 Kartons.","ref":"Lektion 7.1"},{"k":"case","s":"Bei Distrivaud werden Kartons von 400 × 300 mm auf Industriepaletten von 1’200 × 1’000 mm geladen. Die Lernende berechnet die beste Lage.","q":"Wie viele Kartons passen höchstens pro Lage?","a":["9 Kartons","10 Kartons","8 Kartons","12 Kartons"],"ex":"400 auf der Länge: 3 × 3 = 9 (1’000 ÷ 300 = 3.33 → 3). 300 auf der Länge: 4 × 2 = 8. Maximum: 9. Die 10 Kartons aus der Flächenrechnung sind ein theoretisches Maximum, das hier nicht erreichbar ist.","ref":"Lektion 7.1"},{"k":"tf","q":"Dieser Plan zeigt eine volle Lage: Die EUR-Palette ist vollständig mit 12 Kartons von 400 × 200 mm belegt.","v":true,"img":"couche12","ex":"3 × 4 = 12 Kartons; 12 × 80’000 mm² = 960’000 mm², also die ganze Palettenfläche.","ref":"Lektion 7.1"},{"k":"tf","q":"Wenn 800 ÷ 300 = 2.66 ergibt, rundet man auf 3 Kartons in der Breite.","v":false,"ex":"Man rundet immer ab: Ein Stück Karton zählt nicht, also 2.","ref":"Lektion 7.1"},{"k":"tf","q":"Die Palettenfläche geteilt durch die Fläche eines Kartons ergibt ein theoretisches Maximum.","v":true,"ex":"Besser geht es nie. Erreicht man es, ist die Lage perfekt gefüllt.","ref":"Lektion 7.1"},{"k":"pickimg","q":"Welcher Lagenplan zeigt die beste Ausrichtung von Kartons mit 300 × 400 mm auf einer EUR-Palette?","a":["couche8","couche6","couche7"],"ex":"300 auf der Länge: 4 × 2 = 8 Kartons. Die andere Richtung ergibt nur 6 Kartons.","ref":"Lektion 7.1"},{"k":"order","q":"Bringen Sie die Berechnung der Kartons pro Lage in die richtige Reihenfolge.","a":["Alle Masse in mm umrechnen","Länge und Breite der Palette durch die des Kartons dividieren","Jedes Ergebnis abrunden","Die beiden Zahlen multiplizieren","Den Karton drehen und die beste Ausrichtung behalten"],"ex":"Länge durch Länge, Breite durch Breite, abrunden, dann multiplizieren. Beide Richtungen testen.","ref":"Lektion 7.1"},{"k":"num","q":"Maximale Höhe: 1’350 mm. Leere Palette: 150 mm. Kartons: 300 mm hoch. Wie viele Lagen kann man stapeln?","n":4,"tol":0,"u":"Lagen","img":"hauteur","ex":"1’350 − 150 = 1’200 mm. 1’200 ÷ 300 = 4 Lagen.","ref":"Lektion 7.2"},{"k":"case","s":"Das Regalfach bei Stockalp nimmt Ladungen bis höchstens 1’800 mm Höhe auf, EUR-Palette (144 mm) inbegriffen. Die Kartons sind 250 mm hoch.","q":"Wie viele Lagen kann man stapeln?","a":["6 Lagen","7 Lagen","8 Lagen","5 Lagen"],"ex":"1’800 − 144 = 1’656 mm. 1’656 ÷ 250 = 6.62 → 6 Lagen (abgerundet).","ref":"Lektion 7.2"},{"k":"case","s":"Maximale Höhe 1’600 mm, leere Palette 150 mm, Kartons von 200 mm. Ein Kollege sagt «1’600 ÷ 200 = 8 Lagen». Sie kontrollieren seine Rechnung.","q":"Wie viele Lagen kann man tatsächlich stapeln?","a":["7 Lagen","8 Lagen","7.25 Lagen","6 Lagen"],"ex":"Er hat die leere Palette vergessen: 1’600 − 150 = 1’450 mm; 1’450 ÷ 200 = 7.25 → 7 Lagen.","ref":"Lektion 7.2"},{"k":"num","q":"Eine Palette trägt 12 Kartons pro Lage auf 6 Lagen. Wie viele Kartons trägt sie?","n":72,"tol":0,"u":"Kartons","ex":"12 × 6 = 72 Kartons.","ref":"Lektion 7.2"},{"k":"tf","q":"Ergibt die Rechnung 6.9 Lagen, stapelt man 7 Lagen.","v":false,"ex":"Man behält nur volle Lagen: 6 Lagen. Die siebte würde die Grenze überschreiten.","ref":"Lektion 7.2"},{"k":"num","q":"Eine Palette trägt 10 Kartons pro Lage auf 4 Lagen. Wie gross ist ihre Kapazität?","n":40,"tol":0,"u":"Kartons","ex":"10 × 4 = 40 Kartons.","ref":"Lektion 7.3"},{"k":"case","s":"Ein Auftrag von 130 Kartons muss heute Abend raus. Jede Palette trägt 10 Kartons pro Lage auf 4 Lagen. Der Kommissionierer muss leere Paletten reservieren.","q":"Wie viele Paletten müssen bereitgestellt werden?","a":["4 Paletten","3 Paletten","5 Paletten","13 Paletten"],"ex":"Kapazität: 40 Kartons. 130 ÷ 40 = 3.25 → 4 Paletten nötig (aufgerundet: Auch die letzte, unvollständige muss raus).","ref":"Lektion 7.3"},{"k":"num","q":"130 Kartons, 40 Kartons pro Palette: Wie viele Paletten werden voll?","n":3,"tol":0,"u":"Paletten","ex":"130 ÷ 40 = 3.25 → 3 volle Paletten (abgerundet).","ref":"Lektion 7.3"},{"k":"num","q":"130 Kartons, 40 Kartons pro Palette: Wie viele Kartons kommen auf die letzte Palette?","n":10,"tol":0,"u":"Kartons","ex":"130 − 3 × 40 = 10 Kartons.","ref":"Lektion 7.3"},{"k":"case","s":"Logimax muss 500 Kartons versenden. Eine Palette trägt 12 Kartons pro Lage auf 5 Lagen. Der Teamleiter reserviert Paletten und Platz im Lastwagen.","q":"Wie viele Paletten sind nötig?","a":["9 Paletten","8 Paletten","10 Paletten","7 Paletten"],"ex":"Kapazität: 12 × 5 = 60. 500 ÷ 60 = 8.33 → 9 Paletten nötig.","ref":"Lektion 7.3"},{"k":"case","s":"Gleicher Auftrag von 500 Kartons, Paletten zu 60 Kartons (12 pro Lage auf 5 Lagen). Der Kommissionierer will wissen, was auf die letzte Palette kommt.","q":"Wie viele Kartons kommen auf die letzte Palette?","a":["20 Kartons","40 Kartons","60 Kartons","8 Kartons"],"ex":"8 volle Paletten: 8 × 60 = 480. 500 − 480 = 20 Kartons.","ref":"Lektion 7.3"},{"k":"sort","q":"In welche Richtung muss gerundet werden?","c":["Aufrunden","Abrunden"],"it":[["Nötige Paletten für einen Auftrag",0],["Volle Paletten",1],["Lagen unter einer maximalen Höhe",1],["Kartons auf der Länge der Palette",1],["Ladbare Kartons nach Gewicht",1],["Einzusetzende Kommissionierende für einen Auftrag",0]],"ex":"Aufrunden, wenn alles raus oder bearbeitet werden muss. Abrunden, wenn eine Grenze nicht überschritten werden darf.","ref":"Lektion 7.3"},{"k":"num","q":"Maximales Gesamtgewicht (inkl. Palette): 500 kg. Leere Palette: 20 kg. Karton: 10 kg. Der Platz reicht für 50 Kartons. Wie viele Kartons kann man laden?","n":48,"tol":0,"u":"Kartons","ex":"500 − 20 = 480 kg; 480 ÷ 10 = 48. Platz für 50: Man nimmt die kleinere Zahl, 48.","ref":"Lektion 7.4"},{"k":"case","s":"Die Palette von Logipack bietet Platz für 60 Kartons. Das Gesamtgewicht darf 800 kg inkl. Palette nicht überschreiten. Leere Palette: 25 kg; Karton: 14 kg.","q":"Wie viele Kartons kann man tatsächlich laden?","a":["55 Kartons","60 Kartons","57 Kartons","56 Kartons"],"ex":"800 − 25 = 775 kg; 775 ÷ 14 = 55.36 → 55. Platz: 60. Man nimmt die kleinere Zahl: 55 Kartons.","ref":"Lektion 7.4"},{"k":"case","s":"Das Regal nimmt 1’000 kg Last auf der Palette auf (Palette nicht inbegriffen). Die Kartons wiegen 18 kg, und der Platz reicht für 64 Kartons.","q":"Wie viele Kartons kann man laden?","a":["55 Kartons","56 Kartons","54 Kartons","64 Kartons"],"ex":"Die Grenze schliesst die Palette nicht ein: 1’000 ÷ 18 = 55.56 → 55 Kartons (weniger als die 64 vom Platz her).","ref":"Lektion 7.4"},{"k":"qcm","q":"Der Platz reicht für 50 Kartons, das Gewicht erlaubt 48. Wie viele Kartons lädt man?","a":["48 Kartons","50 Kartons","49 Kartons","98 Kartons"],"ex":"Zwei Grenzen: Die kleinere entscheidet.","ref":"Lektion 7.4"},{"k":"match","q":"Ordnen Sie jeder Grösse ihre Formel zu.","p":[["Anzahl Lagen","(Max. Höhe − leere Palette) ÷ Höhe eines Kartons"],["Kapazität einer Palette","Kartons pro Lage × Anzahl Lagen"],["Gesamtgewicht","Leere Palette + Kartons × Gewicht eines Kartons"],["Letzte Palette","Total − volle Paletten × Kapazität"]],"ex":"Formeln der Lektionen 7.2 bis 7.4.","ref":"Lektion 7.4"},{"k":"odd","q":"Finden Sie den Ausreisser: Was begrenzt die Höhe einer beladenen Palette NICHT?","a":["Das Gewicht eines Kartons","Das Regalfach","Die Innenhöhe des Lastwagens","Die Vorgaben des Kunden"],"ex":"Das Gewicht begrenzt die Last, nicht die Höhe.","ref":"Lektion 7.2"},{"k":"multi","q":"Welches sind häufige Fehler bei der Berechnung der Lagen?","good":["Die Höhe der leeren Palette vergessen","Aufrunden","Höhe und Länge des Kartons verwechseln"],"bad":["Die Anzahl Lagen abrunden","Die leere Palette von der maximalen Höhe abziehen"],"ex":"Palette abziehen, durch die Höhe eines Kartons dividieren, abrunden.","ref":"Lektion 7.2"},{"k":"case","s":"Kartons von 400 × 300 × 250 mm (H), je 12 kg, auf EUR-Palette von 144 mm und 25 kg. Max. Höhe 1’400 mm, max. Gesamtgewicht 1’000 kg inkl. Palette.","q":"Wie viele Kartons kann man laden?","a":["40 Kartons","81 Kartons","48 Kartons","45 Kartons"],"ex":"Lage: 8. Lagen: (1’400 − 144) ÷ 250 = 5.02 → 5. Platz: 40. Gewicht: 975 ÷ 12 → 81. Die kleinere Zahl: 40 Kartons.","ref":"Lektion 7.4"}]},{"code":"Mod. 8","t":"Nutzlast und Lastverteilung","g":"Prüfen, ob eine Ladung die Nutzlast des Fahrzeugs einhält","col":"amber","ic":"truckw","ch":[{"k":"qcm","q":"Wie berechnet man die Nutzlast eines Fahrzeugs?","a":["Zulässiges Gesamtgewicht − Leergewicht","Leergewicht − zulässiges Gesamtgewicht","Zulässiges Gesamtgewicht + Leergewicht","Leergewicht − transportierte Last"],"ex":"Nutzlast = zulässiges Gesamtgewicht − Leergewicht.","ref":"Lektion 8.1"},{"k":"num","q":"Ein Lastwagen hat ein zulässiges Gesamtgewicht von 18 t und ein Leergewicht von 8 t. Wie gross ist seine Nutzlast in Tonnen?","n":10,"tol":0,"u":"t","ex":"18 − 8 = 10 t.","ref":"Lektion 8.1"},{"k":"num","q":"Nutzlast: 10’000 kg. Der Lastwagen transportiert 8 Paletten zu 500 kg. Welche Last bleibt verfügbar, in kg?","n":6000,"tol":0,"u":"kg","ex":"8 × 500 = 4’000 kg ; 10’000 − 4’000 = 6’000 kg.","ref":"Lektion 8.1"},{"k":"case","s":"Die Nutzlast des Lastwagens beträgt 10’000 kg, und er trägt bereits 4’000 kg. Ein Kollege zieht zusätzlich das Leergewicht des Lastwagens (8’000 kg) ab und folgert, dass nichts mehr übrig ist.","q":"Was antworten Sie?","a":["Falsch: Die Nutzlast zieht das Leergewicht schon ab","Richtig: Das Lastwagengewicht wird jedes Mal abgezogen","Falsch: Man muss das Leergewicht eher addieren","Richtig: Es bleiben dann genau 2’000 kg übrig"],"ex":"Das Gewicht des Fahrzeugs gehört nie in die Laderechnung: Es ist in der Nutzlast schon abgezogen. Es bleiben 6’000 kg.","ref":"Lektion 8.1"},{"k":"tf","q":"Das Leergewicht des Fahrzeugs gehört in die Berechnung der verfügbaren Last.","v":false,"ex":"Es ist in der Nutzlast bereits abgezogen.","ref":"Lektion 8.1"},{"k":"num","q":"Ein Lieferwagen hat eine Nutzlast von 3.5 t. Er transportiert 2’150 kg. Welche Last bleibt verfügbar, in kg?","n":1350,"tol":0,"u":"kg","ex":"3.5 t = 3’500 kg. 3’500 − 2’150 = 1’350 kg.","ref":"Lektion 8.1"},{"k":"num","q":"Ein Lastwagen hat eine Nutzlast von 12’000 kg. Er transportiert 9’000 kg. Wie hoch ist sein Auslastungsgrad in %?","n":75,"tol":0,"u":"%","ex":"9’000 ÷ 12’000 × 100 = 75 %.","ref":"Lektion 8.2"},{"k":"num","q":"Ein Lastwagen hat eine Nutzlast von 20’000 kg. Er ist zu 85 % ausgelastet. Welche Masse transportiert er, in kg?","n":17000,"tol":0,"u":"kg","ex":"20’000 × 85 ÷ 100 = 17’000 kg.","ref":"Lektion 8.2"},{"k":"case","s":"Der Lastwagen von TransLéman hat eine Nutzlast von 24’000 kg. Heute Abend fährt er mit 17’000 kg los. Der Disponent notiert den Auslastungsgrad, auf eine Dezimale gerundet.","q":"Wie hoch ist der Auslastungsgrad?","a":["70.8 %","70.9 %","141.2 %","29.2 %"],"ex":"17’000 ÷ 24’000 × 100 = 70.83… → 70.8 %.","ref":"Lektion 8.2"},{"k":"qcm","q":"Ein Lastwagen ist zu 75 % seiner Nutzlast beladen. Welcher Anteil bleibt frei?","a":["25 %","75 %","33 %","125 %"],"ex":"100 % − 75 % = 25 %.","ref":"Lektion 8.2"},{"k":"tf","q":"Dividiert man die Nutzlast durch die transportierte Last, erhält man ein Ergebnis über 100 %.","v":true,"ex":"Das ist das Zeichen einer vertauschten Division: Man dividiert die transportierte Last durch die Nutzlast.","ref":"Lektion 8.2"},{"k":"num","q":"Es bleiben 2’000 kg verfügbare Last. Jede Palette wiegt 450 kg. Wie viele Paletten kann man noch laden?","n":4,"tol":0,"u":"Paletten","ex":"2’000 ÷ 450 = 4.44 → 4 Paletten. Kontrolle: 4 × 450 = 1’800 kg; 5 × 450 = 2’250 kg (Überlast).","ref":"Lektion 8.3"},{"k":"case","s":"Ein Kurier-Lastwagen hat noch 3’000 kg verfügbare Last. Die zu ladenden Pakete wiegen je 35 kg. Der Chauffeur will möglichst viele mitnehmen.","q":"Wie viele Pakete kann er noch laden?","a":["85 Pakete","86 Pakete","84 Pakete","87 Pakete"],"ex":"3’000 ÷ 35 = 85.71 → 85 Pakete. Auf 86 zu runden würde die Nutzlast überschreiten (86 × 35 = 3’010 kg).","ref":"Lektion 8.3"},{"k":"tf","q":"Ergibt die Rechnung 4.6 Paletten, kann man noch 5 Paletten laden.","v":false,"ex":"Immer abrunden: 4 Paletten. Eine Überlast wird nie toleriert.","ref":"Lektion 8.3"},{"k":"qcm","q":"Warum rundet man die Anzahl transportierbarer Einheiten immer ab?","a":["Eine Einheit mehr würde die Nutzlast überschreiten","Die Rechner können keine Dezimalen verarbeiten","Der Kunde bezahlt nur ganze Paletten","Das ist die mathematische Regel jeder Rundung"],"ex":"Gesucht ist, was noch dazukommen kann, ohne eine Grenze zu überschreiten.","ref":"Lektion 8.3"},{"k":"sort","q":"In welche Richtung muss gerundet werden?","c":["Aufrunden","Abrunden"],"it":[["Paletten, die noch in den Lastwagen passen",1],["Zusätzliche Pakete im Lieferwagen",1],["Nötige Paletten für den Versand eines Auftrags",0],["Nötige Fahrten, um 50 t mit einem 12-t-Lastwagen zu liefern",0],["Ladbare Kartons unter einer Gewichtsgrenze",1]],"ex":"Einzuhaltende Grenze: abrunden. Alles muss raus: aufrunden.","ref":"Lektion 8.3"},{"k":"num","q":"Ein Lastwagen transportiert 6 Paletten zu 800 kg und 4 Paletten zu 600 kg. Wie hoch ist die transportierte Last in kg?","n":7200,"tol":0,"u":"kg","ex":"6 × 800 = 4’800 ; 4 × 600 = 2’400 ; 4’800 + 2’400 = 7’200 kg.","ref":"Lektion 8.4"},{"k":"case","s":"Der Lastwagen von Logimax hat eine Nutzlast von 12’000 kg. Er transportiert bereits 6 Paletten zu 800 kg und 4 Paletten zu 600 kg. Es sollen Paletten zu 900 kg dazukommen.","q":"Wie viele Paletten zu 900 kg kann er noch laden?","a":["5 Paletten","6 Paletten","13 Paletten","3 Paletten"],"ex":"Transportiert: 7’200 kg. Verfügbar: 4’800 kg. 4’800 ÷ 900 = 5.33 → 5 Paletten.","ref":"Lektion 8.4"},{"k":"case","s":"Ein Sattelauflieger von Transvalor (Nutzlast 18’000 kg) trägt 10 Paletten zu 750 kg und 8 Paletten zu 520 kg. Der Disponent kontrolliert den Auslastungsgrad.","q":"Wie hoch ist der Auslastungsgrad, auf eine Dezimale gerundet?","a":["64.8 %","35.2 %","63.0 %","154.4 %"],"ex":"7’500 + 4’160 = 11’660 kg. 11’660 ÷ 18’000 × 100 = 64.8 %.","ref":"Lektion 8.4"},{"k":"case","s":"Ein Lieferwagen (Nutzlast 1’200 kg) transportiert 15 Pakete zu 32 kg und 6 Pakete zu 48 kg. Der Fahrer will für einen letzten Kunden Pakete zu 25 kg dazuladen.","q":"Wie viele Pakete zu 25 kg kann er noch laden?","a":["17 Pakete","18 Pakete","48 Pakete","30 Pakete"],"ex":"Transportiert: 480 + 288 = 768 kg. Verfügbar: 432 kg. 432 ÷ 25 = 17.28 → 17 Pakete.","ref":"Lektion 8.4"},{"k":"order","q":"Bringen Sie die Methode für eine gemischte Ladung in die richtige Reihenfolge.","a":["Das Gewicht jeder Palettengruppe berechnen","Die Gruppen addieren","Das Total von der Nutzlast abziehen","Durch das Gewicht einer Palette dividieren und abrunden"],"ex":"Gruppe für Gruppe, addieren, von der Nutzlast abziehen, dann dividieren und abrunden.","ref":"Lektion 8.4"},{"k":"match","q":"Ordnen Sie jedem Begriff seine Definition zu.","p":[["Zulässiges Gesamtgewicht","Maximales Gewicht des beladenen Fahrzeugs"],["Leergewicht","Gewicht des Fahrzeugs ohne Ladung"],["Nutzlast","Maximales Gewicht transportierbarer Waren"],["Verfügbare Last","Nutzlast − bereits transportierte Last"]],"ex":"Nutzlast = zulässiges Gesamtgewicht − Leergewicht; verfügbare Last = Nutzlast − transportierte Last.","ref":"Lektion 8.1"},{"k":"multi","q":"Welches sind gute Praktiken der Lastverteilung?","good":["Schwere Paletten unten platzieren","Schwere Paletten zur Mitte der Ladefläche platzieren","Das Gewicht zwischen vorne und hinten ausgleichen","Das Gewicht zwischen links und rechts ausgleichen"],"bad":["Schwere Paletten hinten laden, um schnell zu entladen","Leichte Paletten unter die schweren stellen"],"ex":"Die Nutzlast einzuhalten genügt nicht: Die Verteilung gehört zu einer sicheren Ladung.","ref":"Lektion 8.4"},{"k":"odd","q":"Finden Sie den Ausreisser: Was ist KEIN Fehler?","a":["Mit einer Einheit mehr kontrollieren","Eine Palettengruppe beim Addieren vergessen","Alle Paletten mit einem einzigen Gewicht multiplizieren","Die zusätzlichen Paletten aufrunden"],"ex":"Eine Einheit mehr dazurechnen, um zu prüfen, dass sie die verfügbare Last überschreitet, ist die richtige Kontrolle.","ref":"Lektion 8.4"},{"k":"case","s":"Ein Lieferwagen hat eine Nutzlast von 7.5 t. Er transportiert bereits 5’600 kg Material. Der Lagermitarbeiter will wissen, welche Last er noch dazuladen kann.","q":"Welche Last bleibt verfügbar?","a":["1’900 kg","2’900 kg","190 kg","13’100 kg"],"ex":"7.5 t = 7’500 kg. 7’500 − 5’600 = 1’900 kg. Falle: kg und Tonnen vermischen.","ref":"Lektion 8.1"},{"k":"fill","q":"Nutzlast = zulässiges Gesamtgewicht − ___.","a":["Leergewicht","verfügbare Last","transportierte Last","Gewicht der Paletten"],"ex":"Die Nutzlast ergibt sich aus den Fahrzeugpapieren.","ref":"Lektion 8.1"},{"k":"case","s":"Ein Lastwagen mit 10 t Nutzlast soll mit 14 Paletten zu je 680 kg losfahren. Der Rampenchef kontrolliert die Ladung vor der Abfahrt.","q":"Ist die Ladung vorschriftsgemäss?","a":["Ja: 9’520 kg, es bleiben 480 kg","Nein: 9’520 kg, 480 kg zu viel","Ja: 8’400 kg, es bleiben 1’600 kg","Nein: 14 Paletten sind immer über 10 t"],"ex":"14 × 680 = 9’520 kg ≤ 10’000 kg: vorschriftsgemäss (95.2 %). Es bleiben 480 kg.","ref":"Lektion 8.2"},{"k":"num","q":"Ein Lastwagen hat ein zulässiges Gesamtgewicht von 26 t und ein Leergewicht von 11.2 t. Wie gross ist seine Nutzlast in kg?","n":14800,"tol":0,"u":"kg","img":"charge","ex":"26 − 11.2 = 14.8 t = 14’800 kg.","ref":"Lektion 8.1"},{"k":"case","s":"Der Lieferwagen eines Fahrers (Nutzlast 1’000 kg) trägt bereits 620 kg. Beim letzten Kunden soll er 9 Pakete zu 45 kg mitnehmen.","q":"Was kann er tun?","a":["8 Pakete nehmen: Eines mehr wäre 25 kg zu viel","Alle 9 Pakete nehmen: Die Last bleibt unter 1’000 kg","Nur 7 Pakete nehmen, zur Sicherheit","Nichts nehmen: Der Lieferwagen ist schon voll"],"ex":"Verfügbar: 1’000 − 620 = 380 kg. 380 ÷ 45 = 8.44 → 8 Pakete. Mit 9 Paketen: 620 + 405 = 1’025 kg, 25 kg Überlast.","ref":"Lektion 8.3"}]}];
